// ── Helper functions ────────────────────────────────────────────────────────

/** Flat ordered list of all topic slugs (follows section order) */
const ALL_SLUGS = DEVOPS_SECTIONS.flatMap(s => s.topics);

export const getTopicBySlug = (slug) => DEVOPS_TOPICS[slug] || null;

export const getNextTopic = (slug) => {
  const idx = ALL_SLUGS.indexOf(slug);
  return idx >= 0 && idx < ALL_SLUGS.length - 1 ? DEVOPS_TOPICS[ALL_SLUGS[idx + 1]] : null;
};

export const getPrevTopic = (slug) => {
  const idx = ALL_SLUGS.indexOf(slug);
  return idx > 0 ? DEVOPS_TOPICS[ALL_SLUGS[idx - 1]] : null;
};
